export interface Article {
  title: string;
  pubDate: string;
  link: string;
  guid: string;
  author: string;
  thumbnail: string;
  description: string;
  content: string;
  enclosure: any;
  categories: string[];
}

export interface RSSResponse {
  status: string;
  feed: {
    url: string;
    title: string;
    link: string;
    author: string;
    description: string;
    image: string;
  };
  items: Article[];
}

import { RSSResponse, Article } from '../types';

const RSS_FEED_URL = 'https://andro4all.com/author/christian-collado/feed';
const PROXY_URL = 'https://api.rss2json.com/v1/api.json?rss_url=';

export const fetchLatestArticles = async (limit: number = 5): Promise<Article[]> => {
  try {
    const response = await fetch(`${PROXY_URL}${encodeURIComponent(RSS_FEED_URL)}`);
    if (!response.ok) throw new Error('Failed to fetch articles');

    const data: RSSResponse = await response.json();
    return data.items.slice(0, limit);
  } catch (error) {
    console.error('Error fetching RSS:', error);
    return [];
  }
};

