        className="absolute -top-24 -left-24 w-64 h-64 bg-indigo-600/5 dark:bg-indigo-400/5 rounded-full blur-3xl pointer-events-none opacity-60 will-change-transform"
        style={{ 
          transform: `translate3d(0, calc(var(--scroll-y) * 0.05), 0)` 
        }}
      ></div>
      <div 
        className="absolute -bottom-24 -right-24 w-80 h-80 bg-blue-600/5 dark:bg-blue-400/5 rounded-full blur-3xl pointer-events-none opacity-40 will-change-transform"
        style={{ 
          transform: `translate3d(0, calc(var(--scroll-y) * -0.03), 0)` 
        }}
      ></div>

      {/* Contenido de la tarjeta */}
      <div className="relative z-10">
        {children}
      </div>
    </div>
  );
};

