import { RSSResponse, Article } from '../types';

const RSS_FEED_URL = 'https://andro4all.com/author/christian-collado/feed';
const PROXY_URL = 'https://api.rss2json.com/v1/api.json?rss_url=';

/**
 * Intenta extraer la URL de la imagen principal del contenido HTML del artículo.
 * Busca específicamente el patrón: <img class='type:primaryImage' src="..."
 */
const extractPrimaryImage = (htmlContent: string): string | null => {
  if (!htmlContent) return null;

  // Expresión regular para encontrar el src de una imagen con la clase específica
  const regex = /<img[^>]+class=['"][^'"]*type:primaryImage[^'"]*['"][^>]+src=['"]([^'"]+)['"]/i;
  const match = htmlContent.match(regex);

  if (match && match[1]) {
    return match[1];
  }

  // Fallback 1: Buscar imagen con clase 'featured-image' o similar
  const featuredRegex = /<img[^>]+class=['"][^'"]*featured[^'"]*['"][^>]+src=['"]([^'"]+)['"]/i;
  const featuredMatch = htmlContent.match(featuredRegex);
  if (featuredMatch && featuredMatch[1]) return featuredMatch[1];

  // Fallback 2: buscar cualquier imagen de gran tamaño si la anterior falla
  const fallbackRegex = /<img[^>]+src=['"]([^'"]+)['"]/i;
  const fallbackMatch = htmlContent.match(fallbackRegex);
  return fallbackMatch ? fallbackMatch[1] : null;
};

export const fetchLatestArticles = async (limit: number = 10): Promise<Article[]> => {
  try {
    // Generamos un timestamp único y un número aleatorio para máxima evasión de caché
    const cacheBuster = `cb=${Date.now()}_${Math.floor(Math.random() * 10000)}`;

    // Construimos la URL del feed con el parámetro de busteo
    const targetUrlWithBuster = `${RSS_FEED_URL}${RSS_FEED_URL.includes('?') ? '&' : '?'}${cacheBuster}`;

    // Realizamos la petición a rss2json pidiendo explícitamente más artículos y usando su propio parámetro nocache
    const response = await fetch(`${PROXY_URL}${encodeURIComponent(targetUrlWithBuster)}&count=${limit}&_t=${Date.now()}`);

    if (!response.ok) throw new Error('Failed to fetch articles');

    const data: RSSResponse = await response.json();

    if (data.status !== 'ok') {
       console.error('RSS Proxy Error:', data);
       return [];
    }

    // Procesar artículos para asegurar que tenemos la imagen correcta y datos actualizados
    const processedArticles = data.items.map(article => {
      // Buscamos la imagen en 'content' o 'description'
      const extractedImg = extractPrimaryImage(article.content) || extractPrimaryImage(article.description);

      // Limpiamos el título de entidades HTML si las hubiera
      const cleanTitle = article.title.replace(/&nbsp;/g, ' ').replace(/&#8211;/g, '–').trim();

      return {
        ...article,
        title: cleanTitle,
        thumbnail: extractedImg || article.thumbnail // Preferimos la extraída específicamente
      };
    });

    return processedArticles;
  } catch (error) {
    console.error('Error fetching RSS:', error);
    return [];
  }
};

