import React from 'react';

interface LiquidCardProps {
  children: React.ReactNode;
  className?: string;
}

export const LiquidCard: React.FC<LiquidCardProps> = ({ children, className = '' }) => {
  /**
   * Se elimina 'contain: paint' para evitar artefactos de recorte en navegadores móviles.
   * Se mueve el padding por defecto a una lógica de clase para permitir overrides limpios.
   */
  const defaultPadding = className.includes('p-') ? '' : 'p-8';

  return (
    <div 
      className={`liquid-glass relative overflow-hidden rounded-3xl ${defaultPadding} ${className} transition-all duration-500 hover:border-white/30 group`}
    >
      {/* 
          Capas de gradiente con paralaje optimizado.
          Se mantiene will-change para rendimiento pero se asegura el clipping del padre.
      */}
      <div 
        className="absolute -top-24 -left-24 w-64 h-64 bg-indigo-600/5 dark:bg-indigo-400/5 rounded-full blur-3xl pointer-events-none opacity-60 transform-gpu"
        style={{ 
          transform: `translate3d(0, calc(var(--scroll-y) * 0.05), 0)` 
        }}
      ></div>
      <div 
        className="absolute -bottom-24 -right-24 w-80 h-80 bg-blue-600/5 dark:bg-blue-400/5 rounded-full blur-3xl pointer-events-none opacity-40 transform-gpu"
        style={{ 
          transform: `translate3d(0, calc(var(--scroll-y) * -0.03), 0)` 
        }}
      ></div>

      {/* Contenedor de contenido con z-index alto */}
      <div className="relative z-10 h-full w-full">
        {children}
      </div>
    </div>
  );
};

