                </div>
                <h3 className="text-2xl font-extrabold text-black dark:text-white leading-[1.4] mb-6 group-hover/card:text-indigo-600 dark:group-hover/card:text-indigo-400 transition-colors line-clamp-2">
                  {article.title}
